// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout } from '@stdlib/types/blas';

/**
* Interface describing `dgbtf2`.
*/
interface Routine {
	/**
	* Computes an unblocked LU factorization of a real general band matrix.
	*
	* ## Notes
	*
	* -   The full compact band view is H-by-N, with H=2KL+KU+1 and KV=KL+KU; dense A(i,j) is stored at band row KV+i-j.
	* -   The top KL rows are fill capacity, not original matrix input; source-defined unused cells remain unchanged.
	* -   PIV is output-only positive 1-based stepwise row-swap history, not a final permutation; repeated values are valid.
	* -   A positive INFO identifies the first exactly-zero computed U pivot and does not stop subsequent steps; zero is not a stability certificate.
	* -   KL/KU need not be smaller than matrix dimensions. Dimensions are primitive nonnegative safe integers at most 2147483647.
	* -   Active views require intrinsic ordinary ArrayBuffer backing, including currently valid resizable backing; SharedArrayBuffer is rejected.
	* -   Backing stores must remain stable and exclusively accessed throughout the synchronous call; foreign ordinary buffers sharing physical storage are outside the JS caller contract.
	* -   Full active indexed views must fit, AB must be injective, and AB/PIV indexed-byte envelopes must be disjoint.
	* -   Empty matrices validate the scalar quartet, exact H/KV and main leading dimension, then return zero without array/unused-metadata access, native dispatch or writes.
	* -   Finite active input and finite intermediate arithmetic define the reference-comparison domain; tiny reciprocal overflow is unchanged.
	*
	* @param order - row-major (101) or column-major (102) layout
	* @param M - nonnegative matrix row count, at most 2147483647
	* @param N - nonnegative matrix column count, at most 2147483647
	* @param KL - nonnegative lower bandwidth, at most 2147483647
	* @param KU - nonnegative upper bandwidth, at most 2147483647
	* @param AB - full input/output H-by-N compact band view
	* @param LDAB - leading dimension; at least H column-major or max(1,N) row-major
	* @param PIV - min(M,N) positive 1-based stepwise pivot outputs
	* @throws selectors, active array brands and backing stores must be valid
	* @throws scalar, bounds, injectivity, alias and integer/stride guards must be satisfied
	* @returns numeric INFO, zero or the first zero U pivot position
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var AB = new Float64Array( [ 0.0, 2.0, 0.0 ] );
	* var PIV = new Int32Array( 3 );
	*
	* var info = dgbtf2( 'row-major', 3, 3, 0, 0, AB, 3, PIV );
	* // returns 1
	* // PIV => <Int32Array>[ 1, 2, 3 ]
	* // AB => <Float64Array>[ 0.0, 2.0, 0.0 ]
	*/
	( order: Layout | 101 | 102, M: number, N: number, KL: number, KU: number, AB: Float64Array, LDAB: number, PIV: Int32Array ): number;

	/**
	* Computes an unblocked LU factorization of a real general band matrix.
	*
	* ## Notes
	*
	* -   The full compact band view is H-by-N, with H=2KL+KU+1 and KV=KL+KU; dense A(i,j) is stored at band row KV+i-j.
	* -   The top KL rows are fill capacity, not original matrix input; source-defined unused cells remain unchanged.
	* -   PIV is output-only positive 1-based stepwise row-swap history, not a final permutation; repeated values are valid.
	* -   A positive INFO identifies the first exactly-zero computed U pivot and does not stop subsequent steps; zero is not a stability certificate.
	* -   KL/KU need not be smaller than matrix dimensions. Dimensions are primitive nonnegative safe integers at most 2147483647.
	* -   Active views require intrinsic ordinary ArrayBuffer backing, including currently valid resizable backing; SharedArrayBuffer is rejected.
	* -   Backing stores must remain stable and exclusively accessed throughout the synchronous call; foreign ordinary buffers sharing physical storage are outside the JS caller contract.
	* -   Full active indexed views must fit, AB must be injective, and AB/PIV indexed-byte envelopes must be disjoint.
	* -   Empty matrices validate the scalar quartet, exact H/KV and main leading dimension, then return zero without array/unused-metadata access, native dispatch or writes.
	* -   Finite active input and finite intermediate arithmetic define the reference-comparison domain; tiny reciprocal overflow is unchanged.
	* -   Strides and offsets are element indices relative to the actual typed-array views; signed independent strides are supported.
	* -   Mutable broadcasts with extent greater than one and unsafe exact-index arithmetic are rejected before writes.
	*
	* @param M - nonnegative matrix row count, at most 2147483647
	* @param N - nonnegative matrix column count, at most 2147483647
	* @param KL - nonnegative lower bandwidth, at most 2147483647
	* @param KU - nonnegative upper bandwidth, at most 2147483647
	* @param AB - full input/output H-by-N compact band view
	* @param strideAB1 - band-row element stride
	* @param strideAB2 - matrix-column element stride
	* @param offsetAB - starting band index
	* @param PIV - min(M,N) positive 1-based stepwise pivot outputs
	* @param stridePIV - pivot element stride
	* @param offsetPIV - starting pivot index
	* @throws selectors, active array brands and backing stores must be valid
	* @throws scalar, bounds, injectivity, alias and integer/stride guards must be satisfied
	* @returns numeric INFO, zero or the first zero U pivot position
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var AB = new Float64Array( [ 9.0, 0.0, 2.0, 0.0, 9.0 ] );
	* var PIV = new Int32Array( [ 8, -99, -99, -99, 8 ] );
	*
	* var info = dgbtf2.ndarray( 3, 3, 0, 0, AB, 1, -1, 3, PIV, -1, 3 );
	* // returns 1
	* // PIV => <Int32Array>[ 8, 3, 2, 1, 8 ]
	* // AB => <Float64Array>[ 9.0, 0.0, 2.0, 0.0, 9.0 ]
	*/
	ndarray( M: number, N: number, KL: number, KU: number, AB: Float64Array, strideAB1: number, strideAB2: number, offsetAB: number, PIV: Int32Array, stridePIV: number, offsetPIV: number ): number;
}

/**
* Computes an unblocked LU factorization of a real general band matrix.
*
* @param order - row-major (101) or column-major (102) layout
* @param M - nonnegative matrix row count, at most 2147483647
* @param N - nonnegative matrix column count, at most 2147483647
* @param KL - nonnegative lower bandwidth, at most 2147483647
* @param KU - nonnegative upper bandwidth, at most 2147483647
* @param AB - full input/output H-by-N compact band view
* @param LDAB - leading dimension; at least H column-major or max(1,N) row-major
* @param PIV - min(M,N) positive 1-based stepwise pivot outputs
* @returns numeric INFO, independent of output stepwise pivots
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var AB = new Float64Array( [ 0.0, 2.0, 0.0 ] );
* var PIV = new Int32Array( 3 );
*
* var info = dgbtf2( 'row-major', 3, 3, 0, 0, AB, 3, PIV );
* // returns 1
* // PIV => <Int32Array>[ 1, 2, 3 ]
* // AB => <Float64Array>[ 0.0, 2.0, 0.0 ]
*/
declare var dgbtf2: Routine;


// EXPORTS //

export = dgbtf2;
